<template><section class="curation"><header><div><h1>精选批次与排序</h1><p>只有已通过审核的条目可加入批次；发布后才会在租户精选库出现。</p></div></header><el-card shadow="never"><template #header>新建精选批次</template><el-form :model="form" inline><el-form-item label="市场"><el-select v-model="form.market" style="width:120px"><el-option label="国内" value="domestic"/><el-option label="出海" value="overseas"/></el-select></el-form-item><el-form-item label="渠道"><el-input v-model="form.channel" placeholder="wechat"/></el-form-item><el-form-item label="运营说明"><el-input v-model="form.opsNote" placeholder="可选"/></el-form-item><el-button type="primary" :loading="saving" @click="create">创建草稿批次</el-button></el-form></el-card><el-card class="list" shadow="never"><template #header><span>精选批次</span><el-button text type="primary" @click="load">刷新</el-button></template><el-table v-loading="loading" :data="batches" empty-text="暂无批次"><el-table-column prop="id" label="批次" width="90"><template #default="s">#{{s.row.id}}</template></el-table-column><el-table-column prop="market" label="市场"/><el-table-column prop="channel" label="渠道"/><el-table-column prop="opsNote" label="运营说明"/><el-table-column prop="status" label="状态"><template #default="s"><el-tag :type="s.row.status==='published'?'success':'info'">{{s.row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button v-if="s.row.status==='draft'" text type="success" @click="publish(s.row.id)">发布</el-button><el-button v-if="s.row.status==='published'" text type="danger" @click="offline(s.row.id)">下线</el-button></template></el-table></el-card></section></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{createCurationBatch,getCurationBatches,offlineCurationBatch,publishCurationBatch,type CurationBatch}from'@/api/marketing/curation';defineOptions({name:'AdminCuration'});const loading=ref(false),saving=ref(false),batches=ref<CurationBatch[]>([]),form=reactive({market:'domestic',channel:'wechat',opsNote:''});const load=async()=>{loading.value=true;try{batches.value=await getCurationBatches()}finally{loading.value=false}};const create=async()=>{if(!form.channel.trim())return ElMessage.warning('请填写渠道');saving.value=true;try{await createCurationBatch({...form});ElMessage.success('已创建草稿批次，请先加入审核通过的条目再发布');await load()}finally{saving.value=false}};const publish=async(id:number)=>{await publishCurationBatch(id);ElMessage.success('已发布到租户精选库');await load()};const offline=async(id:number)=>{await offlineCurationBatch(id);ElMessage.success('已下线');await load()};onMounted(load)</script><style scoped>.curation{max-width:1060px;padding:8px 8px 32px}.curation h1{margin:0 0 8px;font-size:22px}.curation p{margin:0 0 18px;color:#6b7280}.list{margin-top:18px}.list :deep(.el-card__header){display:flex;justify-content:space-between}</style>